def _freeze_binding_value(value: object) -> object:
    if isinstance(value, dict):
        return MappingProxyType(
            {str(key): _freeze_binding_value(item) for key, item in value.items()}
        )
    if isinstance(value, list):
        return tuple(_freeze_binding_value(item) for item in value)
    return value


def _formula_input_authority(row: object) -> FormulaInputAuthorityBindingV1:
    if not isinstance(row, dict):
        raise ContractValidationError(
            ReasonCode.INVALID_CONTRACT,
            "formula-input authority row must be an object",
        )
    frozen = _freeze_binding_value(row)
    assert isinstance(frozen, Mapping)
    admitted_mode = row.get("current_admitted_mode")
    if not isinstance(admitted_mode, str):
        raise ContractValidationError(
            ReasonCode.INVALID_CONTRACT,
            "formula-input admitted mode must be exact frozen text",
        )
    try:
        admission_class = FormulaInputAdmissionClassV1(admitted_mode)
    except ValueError as exc:
        raise ContractValidationError(
            ReasonCode.INVALID_CONTRACT,
            "formula-input admitted mode is not in the finite v3.4 projection",
        ) from exc
    return FormulaInputAuthorityBindingV1(
        binding_id=str(row["binding_id"]),
        math_spec_id=str(row["math_spec_id"]),
        input_name=str(row["input_name"]),
        value_state=str(row["value_state"]),
        allowed_origin_class=str(row["allowed_origin_class"]),
        accepted_upstream_owner_id=str(row["accepted_upstream_owner_id"]),
        accepted_packet_or_snapshot_type=str(
            row["accepted_packet_or_snapshot_type"]
        ),
        schema_id=str(row["schema_id"]),
        schema_version=str(row["schema_version"]),
        exact_field_path=str(row["exact_field_path"]),
        input_type=str(row["input_type"]),
        unit_or_basis=str(row["unit_or_basis"]),
        domain=str(row["domain"]),
        required_clock_fields=tuple(
            str(value) for value in row["required_clock_fields"]
        ),
        source_state_and_claim_lineage=str(row["source_state_and_claim_lineage"]),
        provider_native_sequence_or_revision=str(
            row["provider_native_sequence_or_revision"]
        ),
        producer_receipt_type=str(row["producer_receipt_type"]),
        consumer=str(row["consumer"]),
        scope=str(row["scope"]),
        freshness_and_ttl_rule=str(row["freshness_and_ttl_rule"]),
        failure_or_fallback=str(row["failure_or_fallback"]),
        current_admitted_mode=admitted_mode,
        admission_class=admission_class,
        caller_assertion_equality_rule=str(row["caller_assertion_equality_rule"]),
        packet_or_snapshot_identity_resolution_law=str(
            row["packet_or_snapshot_identity_resolution_law"]
        ),
        canonical_typed_value_extraction=str(
            row["canonical_typed_value_extraction"]
        ),
        fixture_assertion_allowed=bool(row["fixture_assertion_allowed"]),
        source_context_computable_from_caller_receipt_alone=bool(
            row["source_context_computable_from_caller_receipt_alone"]
        ),
        terminal_state=str(row["terminal_state"]),
        raw=frozen,
    )


