_PRIMARY_SOURCE_ROWS = tuple(
    _primary_source(row)
    for row in json.loads(_ST12B_PRIMARY_SOURCE_REGISTRY_JSON)
)
PRIMARY_SOURCE_REGISTRY: Mapping[str, PrimarySourceRecordV1] = MappingProxyType(
    {row.source_id: row for row in _PRIMARY_SOURCE_ROWS}
)
SOURCE_POPULATION_COUNTS: Mapping[str, int] = MappingProxyType(
    {
        source_class: sum(
            row.normalized_source_class == source_class
            for row in _PRIMARY_SOURCE_ROWS
        )
        for source_class in (
            "EXTERNAL_PRIMARY_OR_OFFICIAL_SOURCE",
            "OWNER_FORMAL_DERIVATION",
            "OWNER_ARCHITECTURE_OR_POLICY",
        )
    }
)

_SOURCE_CONFLICT_ROWS = tuple(
    _source_conflict(row)
    for row in json.loads(_ST12B_SOURCE_CONFLICT_RESOLUTION_JSON)
)
SOURCE_CONFLICT_RESOLUTIONS: Mapping[
    str, SourceConflictResolutionV1
] = MappingProxyType({row.conflict_id: row for row in _SOURCE_CONFLICT_ROWS})

_SOURCE_CURRENTIZATION_ROWS = tuple(
    _source_currentization(row)
    for row in json.loads(_ST12B_SOURCE_CURRENTIZATION_JSON)
)
SOURCE_CURRENTIZATION_REGISTRY: Mapping[
    str, SourceCurrentizationRecordV1
] = MappingProxyType(
    {row.currentization_id: row for row in _SOURCE_CURRENTIZATION_ROWS}
)

_ONLINE_CURRENTIZATION_ROWS = tuple(
    _online_currentization(row)
    for row in json.loads(_ST12B_ONLINE_CURRENTIZATION_JSON)
)
FROZEN_ONLINE_CURRENTIZATION_RECEIPTS: Mapping[
    str, FrozenOnlineCurrentizationReceiptV1
] = MappingProxyType(
    {row.currentization_id: row for row in _ONLINE_CURRENTIZATION_ROWS}
)

_NUMERIC_VALUE_AUTHORITY_ROWS = tuple(
    _numeric_value_authority(row)
    for row in json.loads(_ST12B_NUMERIC_VALUE_AUTHORITY_JSON)
)
NUMERIC_VALUE_AUTHORITY_BINDINGS: Mapping[
    str, NumericValueAuthorityBindingV1
] = MappingProxyType(
    {row.binding_id: row for row in _NUMERIC_VALUE_AUTHORITY_ROWS}
)

if (
    len(PRIMARY_SOURCE_REGISTRY) != 55
    or dict(SOURCE_POPULATION_COUNTS)
    != {
        "EXTERNAL_PRIMARY_OR_OFFICIAL_SOURCE": 24,
        "OWNER_FORMAL_DERIVATION": 30,
        "OWNER_ARCHITECTURE_OR_POLICY": 1,
    }
    or len(SOURCE_CONFLICT_RESOLUTIONS) != 1
    or len(SOURCE_CURRENTIZATION_REGISTRY) != 7
    or len(FROZEN_ONLINE_CURRENTIZATION_RECEIPTS) != 5
    or len(NUMERIC_VALUE_AUTHORITY_BINDINGS) != 621
    or sum(
        row.subject_kind == "PARAMETER"
        for row in _NUMERIC_VALUE_AUTHORITY_ROWS
    )
    != 479
    or sum(
        row.subject_kind == "FORMULA_INPUT"
        for row in _NUMERIC_VALUE_AUTHORITY_ROWS
    )
    != 142
):
    raise ContractValidationError(
        ReasonCode.INVALID_CONTRACT,
        "v3.4 source/value authority population is not exact",
    )
